"""Shipping helpers for task D2."""

_BASE_COST = {1: 5.0, 2: 12.0, 3: 25.0}


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    US -> 1, CA or MX -> 2, any other code -> 3.
    """
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    """Return base + 1.2 * weight_kg, rounded to 2 decimals.

    The base depends on the zone: 5.0 (zone 1), 12.0 (zone 2), 25.0 (zone 3).
    """
    base = _BASE_COST[zone]
    return round(base + 1.2 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 120 or l + w + h exceeds 300."""
    if l > 120 or w > 120 or h > 120:
        return True
    return l + w + h > 300

